/** An InstructionalRoutine represents a structured, repeatable teaching strategy or pedagogical framework consistently employed within a curriculum to support instructional delivery and student engagement. */
export type InstructionalRoutine = {
  "@id": string;
  "@type": "InstructionalRoutine";
  /** The academic subject */
  academicSubject?: AcademicSubjectENUM;
  /** Specifies the intended audience for a learning resource, indicating who the content is designed for or most relevant to. */
  audience: EducationalAudienceENUM[];
  /** The author of this content. */
  author: string;
  /** A curriculum-specific categorization of the resource. In Illustrative Mathematics, an introductory activity might have curriculumLabel: “warm-up”. */
  curriculumLabel?: string;
  /** The date on which the element was created */
  dateCreated?: string;
  /** A description of the item. */
  description?: string;
  /** This property classifies the resource based on whether it is used for delivering instruction or assessing student learning */
  educationalUse?: EducationalUseENUM;
  /** Specifies the educational grade for which the curriculum component is intended */
  gradeLevel?: GradeLevelENUM[];
  /** Indicates if the activity must be graded */
  gradingRequired?: boolean;
  /** The identifier of the item, either as textual strings or as URL (URI) links. */
  identifier: string;
  /** The language of the content. */
  inLanguage?: LanguageENUM;
  /** Whether the curriculum element is optional to complete */
  isOptional?: boolean;
  /** A license document that applies to this content, typically indicated by URL. */
  license: string;
  /** Indicates the vendor’s guidance regarding whether this learning resource should be included when loading content into a Learning Management System (LMS). This property is advisory and may be overridden by local implementation policies. The value is selected from a controlled vocabulary. */
  lmsLoadingGuidance?: lmsLoadingGuidanceENUM;
  /** The name of the item. */
  name?: string;
  /** The service provider, service operator, or service performer */
  provider?: string;
  /** The date on which the element was created by the provider */
  providerDateCreated: string;
  /** The date on which the element was updated by the provider */
  providerDateModified: string;
};

/** The StandardsFramework entity represents a complete academic standards document published by an official body like a state department of education. They serve as the root entity that organizes and contextualizes all standards within a given framework. */
export type StandardsFramework = {
  "@id": string;
  "@type": "StandardsFramework";
  /** The academic subject. */
  academicSubject: AcademicSubjectENUM;
  /** The adoption status of a framework within a given jurisdiction or governing body. Indicates whether the document has been formally adopted, deprecated, proposed, or otherwise designated for use. */
  adoptionStatus: AdoptionStatusENUM;
  /** A textual credit that acknowledges the source or creator of a work, included when required by the content’s license (e.g., Creative Commons BY). The statement specifies how the creator should be attributed in accordance with the license terms. */
  attributionStatement: string;
  /** The author of this content. */
  author: string;
  /** A URI referencing the equivalent item in the CASE Network published by 1EdTech. This identifier can be used to trace the corresponding standard or structural element in the CASE dataset and establish equivalence between the source and this local representation. */
  caseIdentifierURI: string;
  /** A UUID referencing the equivalent item in the CASE Network published by 1EdTech. This identifier can be used to trace the corresponding standard or structural element in the CASE dataset and establish equivalence between the source and this local representation. */
  caseIdentifierUUID: string;
  /** The date on which the element was created. */
  dateCreated?: string;
  /** The date on which the element was most recently modified. */
  dateModified?: string;
  /** A description of the item. */
  description?: string;
  /** The identifier of the item, either as textual strings or as URL (URI) links. */
  identifier: string;
  /** The language of the content. */
  inLanguage: LanguageENUM;
  /** The geographic, political, or organizational authority under which a standards framework or individual item is published, adopted, or implemented. A jurisdiction typically refers to a state, territory, country, or governing education agency responsible for endorsing or overseeing the framework. */
  jurisdiction: JurisdictionENUM;
  /** A license document that applies to this content, typically indicated by URL. */
  license: string;
  /** The name of the item. */
  name?: string;
  /** An optional, human-readable field that provides additional context, commentary, or clarifying information about a framework, grouping, or standard. */
  notes?: string;
  /** The service provider, service operator, or service performer. */
  provider: string;
  /** A hasChild relationship connects a StandardsFramework to one or more structural StandardsFrameworkItem . These items serve as the top-level organizational elements of the framework that define the initial structure from which lower-level standards or competencies branch. */
  hasChild?: (StandardsFrameworkItem | OcxLink<"StandardsFrameworkItem">)[];
};

/** The StandardsFrameworkItem entity represents an individual statement or structural element within a standards framework. Items may be normative statements (e.g., a standard that specifies what students should know or be able to do) or organizational groupings (e.g., strands, clusters). */
export type StandardsFrameworkItem = {
  "@id": string;
  "@type": "StandardsFrameworkItem";
  /** The academic subject. */
  academicSubject: AcademicSubjectENUM;
  /** A textual credit that acknowledges the source or creator of a work, included when required by the content’s license (e.g., Creative Commons BY). The statement specifies how the creator should be attributed in accordance with the license terms. */
  attributionStatement: string;
  /** The author of this content. */
  author: string;
  /** A URI referencing the equivalent item in the CASE Network published by 1EdTech. This identifier can be used to trace the corresponding standard or structural element in the CASE dataset and establish equivalence between the source and this local representation. */
  caseIdentifierURI: string;
  /** A UUID referencing the equivalent item in the CASE Network published by 1EdTech. This identifier can be used to trace the corresponding standard or structural element in the CASE dataset and establish equivalence between the source and this local representation. */
  caseIdentifierUUID: string;
  /** The date on which the element was created. */
  dateCreated?: string;
  /** The date on which the element was most recently modified. */
  dateModified?: string;
  /** A description of the item. */
  description?: string;
  /** Specifies the educational grade for which the curriculum component is intended. */
  gradeLevel?: GradeLevelENUM[];
  /** The identifier of the item, either as textual strings or as URL (URI) links. */
  identifier: string;
  /** The language of the content. */
  inLanguage: LanguageENUM;
  /** The geographic, political, or organizational authority under which a standards framework or individual item is published, adopted, or implemented. A jurisdiction typically refers to a state, territory, country, or governing education agency responsible for endorsing or overseeing the framework. */
  jurisdiction: JurisdictionENUM;
  /** A license document that applies to this content, typically indicated by URL. */
  license: string;
  /** A normalized value that describes the broad functional role of a StandardsFrameworkItem within a standards framework. This classification distinguishes between instructional targets, structural elements, and supportive or contextual content, regardless of how those elements are labeled or structured in individual state or national standards. */
  normalizedStatementType: NormalizedStatementTypeENUM;
  /** An optional, human-readable field that provides additional context, commentary, or clarifying information about a framework, grouping, or standard. */
  notes?: string;
  /** The service provider, service operator, or service performer. */
  provider: string;
  /** A short, human-readable code that uniquely identifies a StandardsFrameworkItem within its immediate context. Typically used to refer to standards or elements in official documents, curriculum materials, or assessment systems. The statementCode is often alphanumeric (e.g., “3.NF.A.1”, “A.1B”, “MP1”) and reflects the framework’s internal coding scheme. */
  statementCode?: string;
  /** A framework-specific classification that describes the local role or label of a StandardsFrameworkItem as defined by its source framework. Unlike the normalized frameworkItemType, which generalizes across systems, statementType preserves the vocabulary and taxonomy used in the originating standards (e.g., “Domain”, “Cluster”, “Strand”, “Benchmark”, “Practice Standard”). */
  statementType?: string;
  /** A hasChild relationship connects a StandardsFramework to one or more structural StandardsFrameworkItem . These items serve as the top-level organizational elements of the framework that define the initial structure from which lower-level standards or competencies branch. */
  hasChild?: (StandardsFrameworkItem | OcxLink<"StandardsFrameworkItem">)[];
};

/** A digital or physical media object that embodies a specific version, format, or instance of a Material, making it accessible or consumable by users. */
export type Representation = {
  "@id": string;
  "@type": "Representation";
  /** The identifier of the item, either as textual strings or as URL (URI) links. */
  identifier: string;
  /** MIME type of the representation (e.g., 'application/pdf', 'text/html'). */
  encodingFormat: string;
  /** URL, path, or inline content providing access to the resource. */
  accessResource: string;
  /** TRUE if this is the preferred representation among multiple formats. */
  preferred?: boolean;
  /** TRUE if generated during OCX packaging, FALSE if from source system. */
  isOcxGenerated?: boolean;
  /** Vendor guidance on whether this representation should be loaded into an LMS. */
  lmsLoadingGuidance?: lmsLoadingGuidanceENUM;
  /** Name of the representation (e.g., 'Spanish PDF'). */
  name?: string;
  /** Description of the representation. */
  description?: string;
  /** Language of this representation, if different from the parent Material. */
  inLanguage?: LanguageENUM;
  /** When this representation was created. */
  dateCreated?: string;
  /** When this representation was last modified. */
  dateModified?: string;
};

export type OcxEntity =
  | Course
  | LessonGrouping
  | Lesson
  | Activity
  | Assessment
  | Material
  | ClassroomMaterial
  | GlossaryTerm
  | InstructionalRoutine
  | StandardsFramework
  | StandardsFrameworkItem
  | Representation;
